export const userFields = ["id","email","age","newsletter"];

/** Validation errors for a user object (empty when it is valid). */
export function validateUser(value) {
  const errors = [];
  if (value.id === undefined) errors.push("id is required");
  else if (typeof value.id !== "string") errors.push("id must be a string");
  if (value.email === undefined) errors.push("email is required");
  else if (typeof value.email !== "string") errors.push("email must be a string");
  if (!(value.age === undefined) && !Number.isInteger(value.age)) errors.push("age must be an integer");
  if (!(value.newsletter === undefined) && typeof value.newsletter !== "boolean") errors.push("newsletter must be a boolean");
  for (const key of Object.keys(value)) {
    if (!userFields.includes(key)) errors.push(`unknown field ${key}`);
  }
  return errors;
}
